+import { treaty } from "@elysiajs/eden";
+import { createFileRoute } from "@tanstack/react-router";
+import { createIsomorphicFn, createServerOnlyFn } from "@tanstack/react-start";
+
+import type { ApiApp } from "../server/api";
+
+const handle = createServerOnlyFn(async ({ request }: { request: Request }) => {
+  const { apiApp } = await import("../server/api");
+  return apiApp.fetch(request);
+});
+
+export const Route = createFileRoute("/api/$")({
+  server: {
+    handlers: {
+      DELETE: handle,
+      GET: handle,
+      HEAD: handle,
+      OPTIONS: handle,
+      PATCH: handle,
+      POST: handle,
+      PUT: handle,
+    },
+  },
+});
+
+export const getTreaty = createIsomorphicFn()
+  .server(async () => {
+    const { apiApp } = await import("../server/api");
+    return treaty(apiApp).api;
+  })
+  .client(() => treaty<ApiApp>(window.location.origin).api);

