@@ -0,0 +1,20 @@
+import { type AuthEnvironment, createAuth } from "./auth";
+
+const rootAuthorizationServerPath = "/.well-known/oauth-authorization-server";
+
+export async function handleRootOAuthAuthorizationServerMetadata(
+  request: Request,
+  environment: AuthEnvironment,
+): Promise<Response | undefined> {
+  if (request.method !== "GET") return undefined;
+
+  const pathname = new URL(request.url).pathname.replace(/\/$/, "");
+  if (
+    pathname !== rootAuthorizationServerPath &&
+    pathname !== `${rootAuthorizationServerPath}/api/auth`
+  ) {
+    return undefined;
+  }
+
+  return createAuth(environment).handler(request);
+}

