+import type { ExportedHandler } from "@cloudflare/workers-types";
+import startHandler from "@tanstack/react-start/server-entry";
+
+import { handleRootOAuthAuthorizationServerMetadata } from "./server/metadata";
+
+const worker: ExportedHandler<Cloudflare.Env, unknown> = {
+  async fetch(request, environment, _context) {
+    const metadataResponse = await handleRootOAuthAuthorizationServerMetadata(request, environment);
+    if (metadataResponse) return metadataResponse;
+
+    return startHandler.fetch(request);
+  },
+
+  queue(batch) {
+    for (const message of batch.messages) {
+      message.ack();
+    }
+  },
+
+  scheduled(controller) {
+    console.info("Mikan scheduled handler invoked", { cron: controller.cron });
+  },
+};
+
+export default worker;

