+import { Elysia, t } from "elysia";
+import { env } from "cloudflare:workers";
+
+import { createAuth, type AuthEnvironment } from "./auth";
+
+const apiMethods = ["GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS", "HEAD"] as const;
+
+function createAuthHandler(environment: AuthEnvironment) {
+  return ({ request }: { request: Request }) => createAuth(environment).handler(request);
+}
+
+export function createApiApp(environment: AuthEnvironment) {
+  const authHandler = createAuthHandler(environment);
+
+  return new Elysia({ prefix: "/api" })
+    .get(
+      "/health",
+      () => ({
+        service: "mikan-api",
+        status: "ok" as const,
+      }),
+      {
+        response: t.Object({
+          service: t.String(),
+          status: t.Literal("ok"),
+        }),
+      },
+    )
+    .head("/health", () => new Response(null, { status: 204 }))
+    .get("/auth", authHandler)
+    .post("/auth", authHandler)
+    .put("/auth", authHandler)
+    .patch("/auth", authHandler)
+    .delete("/auth", authHandler)
+    .options("/auth", authHandler)
+    .head("/auth", authHandler)
+    .get("/auth/*", authHandler)
+    .post("/auth/*", authHandler)
+    .put("/auth/*", authHandler)
+    .patch("/auth/*", authHandler)
+    .delete("/auth/*", authHandler)
+    .options("/auth/*", authHandler)
+    .head("/auth/*", authHandler);
+}
+
+export const apiApp = createApiApp(env);
+
+export type ApiApp = typeof apiApp;
+
+export const supportedApiMethods = apiMethods;

