display.text:
import { useForm } from "@tanstack/react-form";
import { createFileRoute, Link } from "@tanstack/react-router";
import { useState } from "react";

import { Button } from "../components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "../components/ui/card";
import { Input } from "../components/ui/input";

export const Route = createFileRoute("/sign-in")({
  component: SignInPage,
});

function SignInPage() {
  const [message, setMessage] = useState<string>();
  const form = useForm({
    defaultValues: {
      email: "",
      password: "",
    },
    onSubmit: async ({ value }) => {
      const response = await fetch("/api/auth/sign-in/email", {
        body: JSON.stringify(value),
        headers: { "content-type": "application/json" },
        method: "POST",
      });

      setMessage(response.ok ? "Signed in. Redirecting soon." : "The credentials could not be verified.");
    },
  });

  return (
    <section className="mx-auto grid max-w-6xl gap-10 px-5 py-14 sm:px-8 sm:py-20 lg:grid-cols-[0.8fr_1.2fr] lg:items-center">
      <div className="hidden lg:block">
        <p className="text-sm font-medium uppercase tracking-[0.18em] text-[var(--tangerine)]">Welcome back</p>
        <h1 className="mt-5 max-w-md font-display text-5xl font-semibold leading-none tracking-[-0.05em] text-white">
          Your identity, with fewer sharp edges.
        </h1>
        <p className="mt-6 max-w-md leading-7 text-white/55">
          Sign in to manage the applications and people connected to your organization.
        </p>
      </div>
      <Card className="mx-auto w-full max-w-md border-white/10 bg-white/[0.06]">
        <CardHeader>
          <CardTitle className="text-2xl text-white">Sign in to Mikan</CardTitle>
          <CardDescription className="text-white/50">
            Use your Mikan email and password to continue.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form
            className="space-y-5"
            onSubmit={(event) => {
              event.preventDefault();
              event.stopPropagation();
              void form.handleSubmit();
            }}
          >
            <form.Field name="email">
              {(field) => (
                <label className="block space-y-2 text-sm text-white/70">
                  Email
                  <Input
                    autoComplete="email"
                    onBlur={field.handleBlur}
                    onChange={(event) => field.handleChange(event.target.value)}
                    placeholder="you@example.com"
                    type="email"
                    value={field.state.value}
                  />
                </label>
              )}
            </form.Field>
            <form.Field name="password">
              {(field) => (
                <label className="block space-y-2 text-sm text-white/70">
                  Password
                  <Input
                    autoComplete="current-password"
                    onBlur={field.handleBlur}
                    onChange={(event) => field.handleChange(event.target.value)}
                    placeholder="••••••••"
                    type="password"
                    value={field.state.value}
                  />
                </label>
              )}
            </form.Field>
            <Button className="w-full" type="submit">
              Continue securely
            </Button>
            {message ? <p className="text-sm text-white/60">{message}</p> : null}
          </form>
          <p className="mt-6 text-center text-sm text-white/45">
            Need an invitation? Ask your Mikan administrator.
          </p>
          <Link className="mt-4 block text-center text-sm text-(--tangerine) hover:underline" to="/">
            Return home
          </Link>
        </CardContent>
      </Card>
    </section>
  );
}

