import { cva, type VariantProps } from "class-variance-authority";
import {
  cloneElement,
  forwardRef,
  isValidElement,
  type ButtonHTMLAttributes,
} from "react";

import { cn } from "../../lib/utils";

const buttonVariants = cva(
  "inline-flex items-center justify-center whitespace-nowrap rounded-full text-sm font-semibold transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--tangerine)] disabled:pointer-events-none disabled:opacity-50",
  {
    variants: {
      size: {
        default: "h-11 px-5",
        lg: "h-13 px-7 text-base",
        sm: "h-9 px-4 text-xs",
      },
      variant: {
        default: "bg-[var(--tangerine)] text-[var(--ink)] shadow-lg shadow-[var(--tangerine)]/15 hover:bg-[#ff956d]",
        ghost: "text-white/65 hover:bg-white/10 hover:text-white",
        outline: "border border-white/15 bg-white/[0.04] text-white hover:bg-white/10",
      },
    },
    defaultVariants: {
      size: "default",
      variant: "default",
    },
  },
);

export interface ButtonProps
  extends ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean;
}

const Button = forwardRef<HTMLButtonElement, ButtonProps>(
  ({ asChild = false, className, size, variant, ...props }, ref) => {
    if (asChild) {
      const child = props.children;
      if (!isValidElement<{ className?: string }>(child)) return null;
      return cloneElement(child, {
        className: cn(buttonVariants({ size, variant }), className),
      });
    }

    return (
      <button className={cn(buttonVariants({ size, variant }), className)} ref={ref} {...props} />
    );
  },
);
Button.displayName = "Button";

export { Button, buttonVariants };

