import { drizzleAdapter } from "@better-auth/drizzle-adapter";
import { oauthProvider } from "@better-auth/oauth-provider";
import { betterAuth, type BetterAuthPlugin } from "better-auth";
import { jwt } from "better-auth/plugins";

import { createDb } from "../db";
import * as authSchema from "../db/auth-schema";

export type AuthEnvironment = Pick<Cloudflare.Env, "DB"> &
  Partial<Pick<Cloudflare.Env, "BETTER_AUTH_SECRET" | "BETTER_AUTH_URL">>;

export function createAuth(environment: AuthEnvironment) {
  return betterAuth({
    ...(environment.BETTER_AUTH_URL ? { baseURL: environment.BETTER_AUTH_URL } : {}),
    database: drizzleAdapter(createDb(environment.DB), {
      provider: "sqlite",
      schema: authSchema,
      transaction: false,
    }),
    disabledPaths: ["/token"],
    emailAndPassword: {
      enabled: true,
    },
    plugins: [
      jwt({
        disableSettingJwtHeader: true,
      }),
      oauthProvider({
        consentPage: "/consent",
        grantTypes: ["authorization_code", "client_credentials"],
        loginPage: "/sign-in",
        scopes: ["openid", "profile", "email"],
      }) as BetterAuthPlugin,
    ],
    ...(environment.BETTER_AUTH_SECRET ? { secret: environment.BETTER_AUTH_SECRET } : {}),
  });
}

